INSERT INTO career_task (id, level_id, title, description, points_value, is_active, created_by, created_at) VALUES
('tsk0001', 'lvl0001', 'Create a Professional LinkedIn Profile', 'Set up a professional LinkedIn profile outlining your programming skills, bio, and educational credentials to begin networking with peers.', 50, 1, 'usr0001', NOW()),
('tsk0002', 'lvl0001', 'Write a Technical Blog Article', 'Author a short article on Medium or Dev.to explaining a basic programming concept (e.g. loops or arrays) to practice technical communication.', 50, 1, 'usr0001', NOW()),
('tsk0003', 'lvl0002', 'Build a Responsive HTML/CSS Portfolio Website', 'Design and code a multi-page personal portfolio showcasing your projects. It must be mobile-friendly and deployed on GitHub Pages.', 100, 1, 'usr0001', NOW()),
('tsk0004', 'lvl0002', 'Interactive JavaScript CLI Utility', 'Write a node command line application that accepts inputs and processes files or fetches data from a public API.', 100, 1, 'usr0001', NOW()),
('tsk0005', 'lvl0003', 'Develop a Restful Spring Boot Backend API', 'Implement a REST service utilizing JPA Hibernate mappings to manage a relational database schema. Must include security validation.', 150, 1, 'usr0002', NOW()),
('tsk0006', 'lvl0003', 'Integrate OAuth2 Authentication Flow', 'Add secure Google or GitHub social login to your backend using standard OAuth2 protocols.', 150, 1, 'usr0002', NOW()),
('tsk0007', 'lvl0004', 'Implement Comprehensive JUnit Test Suite', 'Write thorough unit and integration test assertions reaching 85% coverage on your application controllers and service implementations.', 200, 1, 'usr0002', NOW()),
('tsk0008', 'lvl0004', 'Performance Audit and Database Index Optimization', 'Analyze slow SQL execution plans and introduce database indexes to optimize table scan operations.', 200, 1, 'usr0002', NOW()),
('tsk0009', 'lvl0005', 'Design Microservices System Topology', 'Draft a system architecture blueprint mapping microservices communication patterns, API gateway configuration, and registry protocols.', 250, 1, 'usr0003', NOW()),
('tsk0010', 'lvl0005', 'Configure Distributed Tracing', 'Integrate Zipkin or Jaeger telemetry trackers to capture request flows across microservice clusters.', 250, 1, 'usr0003', NOW()),
('tsk0011', 'lvl0006', 'Docker Containerization and Docker Compose Orchestration', 'Write multi-stage Dockerfiles for your services and orchestrate local execution dependencies using docker-compose.', 300, 1, 'usr0003', NOW()),
('tsk0012', 'lvl0006', 'Set up Automated CI/CD Jenkins Pipeline', 'Write a Jenkinsfile automating build stages, static security scans, unit tests, and image deployment on repository triggers.', 300, 1, 'usr0003', NOW()),
('tsk0013', 'lvl0007', 'Multi-Region Cloud Deployment & High Availability Disaster Recovery', 'Architect and implement terraform modules deploying highly resilient clusters across separate AWS regions with active replication.', 500, 1, 'usr0003', NOW());
